#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pwd.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_PATH 4096
#define MAX_DATA (1024 * 1024)
#define SALT_LEN 16
#define IV_LEN 12
#define TAG_LEN 16
#define KEY_LEN 32
#define ITERATIONS 100000

typedef struct {
    char path[MAX_PATH];
    unsigned char *data;
    size_t data_len;
    uid_t owner;
    mode_t mode;
} secure_file_t;

/* Derive encryption key from password using PBKDF2 */
static int derive_key(const char *password, const unsigned char *salt,
                      unsigned char *key) {
    if (!password || !salt || !key) return -1;
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, SALT_LEN,
                           ITERATIONS, EVP_sha256(), KEY_LEN, key) != 1) {
        return -1;
    }
    return 0;
}

/* Encrypt data using AES-256-GCM */
static int encrypt_data(const unsigned char *key, const unsigned char *plaintext,
                        size_t pt_len, unsigned char *output, size_t *out_len) {
    EVP_CIPHER_CTX *ctx = NULL;
    unsigned char iv[IV_LEN];
    unsigned char tag[TAG_LEN];
    int len = 0;
    int ct_len = 0;
    int ret = -1;

    if (RAND_bytes(iv, IV_LEN) != 1) goto done;

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) goto done;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1) goto done;
    if (EVP_EncryptUpdate(ctx, output + IV_LEN + SALT_LEN, &len, plaintext, pt_len) != 1) goto done;
    ct_len = len;
    if (EVP_EncryptFinal_ex(ctx, output + IV_LEN + SALT_LEN + ct_len, &len) != 1) goto done;
    ct_len += len;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, tag) != 1) goto done;

    memcpy(output + IV_LEN + SALT_LEN + ct_len, tag, TAG_LEN);
    memcpy(output, iv, IV_LEN);
    *out_len = IV_LEN + SALT_LEN + ct_len + TAG_LEN;
    ret = 0;

done:
    EVP_CIPHER_CTX_free(ctx);
    return ret;
}

/*
 * Write encrypted data to a secure file.
 * Opens file with O_NOFOLLOW|O_CREAT|O_WRONLY|O_EXCL to prevent symlink attacks,
 * then validates the opened fd with fstat before writing.
 */
int secure_write(const char *filepath, const char *password,
                 const unsigned char *data, size_t data_len) {
    unsigned char salt[SALT_LEN];
    unsigned char key[KEY_LEN];
    unsigned char *encrypted = NULL;
    size_t enc_len = 0;
    int fd = -1;
    FILE *fp = NULL;
    struct stat st;
    int ret = -1;
    uid_t our_uid = getuid();
    char resolved[MAX_PATH];
    char dir_path[MAX_PATH];
    char *last_slash;

    if (!filepath || !password || !data) return -1;
    if (data_len == 0 || data_len > MAX_DATA) return -1;
    if (strlen(filepath) >= MAX_PATH) return -1;

    /* Validate path doesn't contain traversal */
    if (strstr(filepath, "..") != NULL) {
        fprintf(stderr, "Path traversal detected\n");
        return -1;
    }

    /* Verify parent directory safety */
    strncpy(dir_path, filepath, MAX_PATH - 1);
    dir_path[MAX_PATH - 1] = '\0';
    last_slash = strrchr(dir_path, '/');
    if (last_slash) {
        struct stat dir_st;
        *last_slash = '\0';
        if (stat(dir_path, &dir_st) != 0) return -1;
        if (dir_st.st_uid != our_uid) {
            fprintf(stderr, "Parent directory not owned by us\n");
            return -1;
        }
        if (dir_st.st_mode & S_IWOTH) {
            fprintf(stderr, "Parent directory is world-writable\n");
            return -1;
        }
    }

    /* Generate random salt */
    if (RAND_bytes(salt, SALT_LEN) != 1) return -1;

    /* Derive key */
    if (derive_key(password, salt, key) != 0) goto cleanup;

    /* Allocate output buffer: IV + salt + ciphertext + tag */
    encrypted = malloc(IV_LEN + SALT_LEN + data_len + TAG_LEN + 16);
    if (!encrypted) goto cleanup;

    /* Copy salt to output */
    memcpy(encrypted + IV_LEN, salt, SALT_LEN);

    /* Encrypt */
    if (encrypt_data(key, data, data_len, encrypted, &enc_len) != 0) goto cleanup;

    /* Remove existing file first, then open with O_CREAT|O_EXCL|O_NOFOLLOW
     * This ensures we create a NEW file (not follow a symlink) */
    unlink(filepath);  /* ignore error - file may not exist */

    fd = open(filepath, O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW, 0600);
    if (fd < 0) {
        fprintf(stderr, "Cannot create file securely: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Verify the opened fd points to a regular file owned by us */
    if (fstat(fd, &st) != 0) goto cleanup;
    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Not a regular file\n");
        goto cleanup;
    }
    if (st.st_uid != our_uid) {
        fprintf(stderr, "File not owned by us after creation\n");
        goto cleanup;
    }

    /* Convert fd to FILE* for buffered writing */
    fp = fdopen(fd, "wb");
    if (!fp) goto cleanup;
    fd = -1;  /* fp now owns the fd */

    if (fwrite(encrypted, 1, enc_len, fp) != enc_len) goto cleanup;

    ret = 0;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    if (encrypted) {
        memset(encrypted, 0, IV_LEN + SALT_LEN + data_len + TAG_LEN + 16);
        free(encrypted);
    }
    memset(key, 0, KEY_LEN);
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <filepath> <password> <data>\n", argv[0]);
        return 1;
    }

    const char *filepath = argv[1];
    const char *password = argv[2];
    const unsigned char *data = (const unsigned char *)argv[3];
    size_t data_len = strlen(argv[3]);

    if (secure_write(filepath, password, data, data_len) != 0) {
        fprintf(stderr, "Failed to write secure file\n");
        return 1;
    }

    printf("Data written securely to %s\n", filepath);
    return 0;
}
